import unreal
ar = unreal.AssetRegistryHelpers.get_asset_registry()
for data in ar.get_assets_by_path('/Game/_Game', recursive=True):
    cls = str(data.asset_class_path.asset_name)
    if cls not in ('WidgetBlueprint', 'Blueprint'):
        continue
    path = f'{data.package_name}.{data.asset_name}'
    asset = unreal.load_asset(path)
    if not asset:
        continue
    if cls == 'WidgetBlueprint':
        wbp = asset
        if wbp.widget_tree and wbp.widget_tree.root_widget:
            def walk(w, depth=0):
                try:
                    t = w.get_display_label() or w.get_name()
                except:
                    t = w.get_name()
                blob = str(t)
                if hasattr(w, 'get_text'):
                    try:
                        blob += ' ' + str(w.get_text())
                    except: pass
                if any(x in blob for x in ('Responder','Callarse','Ignorar','Salir')):
                    unreal.log(f'WIDGET HIT {path}: {blob}')
                if hasattr(w, 'get_children_count'):
                    for i in range(w.get_children_count()):
                        walk(w.get_child_at(i), depth+1)
            walk(wbp.widget_tree.root_widget)
    elif hasattr(asset, 'simple_construction_script'):
        for node in asset.simple_construction_script.get_all_nodes():
            comp = node.component_template
            if comp and 'Widget' in comp.get_class().get_name():
                unreal.log(f'BP widget comp {path}: {comp.get_name()} class={comp.get_class().get_name()}')
